// Generated by wikiloop build from the core on-call screen; edit wikiloop.toml [oncall], not this file.
export type ItemLink = { label: string; href: string }

export type Item = {
  id: string
  label: string
  severity: string
  tier: string
  what: string
  error: string
  age: string
  isNew: boolean
  links: ItemLink[]
}

export type SectionStyle = 'full' | 'compact' | 'inline'

export type Section = {
  title: string
  status: 'open' | 'resolved'
  color: string
  style: SectionStyle
  empty: string
  count: number
  items: Item[]
  more: number
  folded: number
  foldedLabel: string
}

export type Snapshot = {
  updatedMs: number
  staleMinutes: number
  counts: Record<string, number>
  fresh: Item[]
  loud: Item[]
  sections: Section[]
}

export type SeverityDef = { name: string; rank: number; color: string }

export type SectionDef = {
  title: string
  status: 'open' | 'resolved'
  minSeverity: string
  maxSeverity: string
  chronic: 'any' | 'only' | 'exclude'
  isNew: 'any' | 'only' | 'exclude'
  style: SectionStyle
  color: string
  limit: number
  empty: string
  foldBelow: boolean
}

declare module 'claude-code' {
  interface PluginState {
    // startedMs: when the command asked for a watch, 0 once its first cycle landed or it never came
    // off: `off` hid the line and the pane until the command runs again
    '__PLUGIN__': { snapshot: Snapshot | null; autoOpened: boolean; startedMs: number; off: boolean }
  }
}
